"""
Test fixtures for Noxrea AI Canvas backend tests.

Creates an isolated in-memory SQLite database, applies schema,
and provides authenticated test clients.
"""

import hashlib
import os
import pytest
import pytest_asyncio
from typing import AsyncGenerator

from httpx import ASGITransport, AsyncClient
from sqlalchemy import text as _sql
from sqlalchemy.ext.asyncio import AsyncSession, create_async_engine, async_sessionmaker

from app.database import Base
from app.main import app
from app.config import settings
from app.deps import get_db, get_current_user

# ── Override settings for tests ──────────────────────────────────

TEST_UPLOAD_DIR = os.path.join(os.path.dirname(__file__), "fixtures", ".test_uploads")
os.environ["DATABASE_URL"] = "sqlite+aiosqlite://"
os.environ["JWT_SECRET_KEY"] = "test-secret-key-for-tests-only"
os.environ["ADMIN_PASSWORD"] = "test-admin"
os.environ["PUBLIC_URL"] = "http://testserver"
os.environ["INFERENCE_SERVICE_URL"] = "http://localhost:8100"
os.environ["INFERENCE_SERVICE_API_KEY"] = ""

# Reload settings from overridden env
from app.config import settings as _s

# Patch UPLOAD_DIR in files.py and services/media.py (module-level constants)
import app.routers.files as _files_mod
_files_mod.UPLOAD_DIR = TEST_UPLOAD_DIR
_files_mod.CACHE_DIR = os.path.join(TEST_UPLOAD_DIR, "_cache")

import app.services.media as _media_mod
_media_mod.UPLOAD_DIR = TEST_UPLOAD_DIR

# ── In-memory engine + session ──────────────────────────────────

_engine = create_async_engine("sqlite+aiosqlite://", echo=False)
_async_session = async_sessionmaker(_engine, class_=AsyncSession, expire_on_commit=False)


async def _init_db():
    """Create all tables."""
    async with _engine.begin() as conn:
        await conn.run_sync(Base.metadata.create_all)


async def _drop_db():
    """Drop all tables."""
    async with _engine.begin() as conn:
        await conn.run_sync(Base.metadata.drop_all)


# ── Fixtures ─────────────────────────────────────────────────────


@pytest_asyncio.fixture(scope="session")
async def db_engine():
    await _init_db()
    yield _engine
    await _drop_db()
    await _engine.dispose()


@pytest_asyncio.fixture
async def db(db_engine) -> AsyncGenerator[AsyncSession, None]:
    """Fresh session per test wrapped in a transaction that rolls back.

    Even though the app calls commit(), the outer transaction is rolled back
    after each test, keeping tests isolated.
    """
    connection = await db_engine.connect()
    transaction = await connection.begin()
    session = AsyncSession(bind=connection, expire_on_commit=False, autoflush=False)
    try:
        yield session
    finally:
        await session.close()
        await transaction.rollback()
        await connection.close()


def _override_get_db():
    """Dependency override that yields a per-test session."""
    # This is a placeholder — we inject the actual session per test via the client fixture
    raise NotImplementedError("Use async_client fixture which overrides get_db")


