@pytest_asyncio.fixture
async def test_user(db: AsyncSession) -> dict:
    """Create and return a test user."""
    from app.services.auth import hash_password, ensure_admin_exists

    # ensure_admin_exists creates the default admin user
    await ensure_admin_exists(db)

    result = await db.execute(_sql("SELECT id, username FROM users WHERE username = 'admin'"))
    row = result.fetchone()
    return {"id": row[0], "username": row[1]}


@pytest_asyncio.fixture
async def auth_token(test_user) -> str:
    """Generate a valid JWT for the test user."""
    from app.services.auth import create_access_token
    return create_access_token({"sub": str(test_user["id"])})


@pytest_asyncio.fixture
async def auth_headers(auth_token) -> dict:
    return {"Authorization": f"Bearer {auth_token}"}


# ── Test client ──────────────────────────────────────────────────


@pytest_asyncio.fixture
async def async_client(db: AsyncSession, auth_headers: dict) -> AsyncGenerator[AsyncClient, None]:
    """HTTP client with auth headers and a fresh DB session injected."""

    async def _get_db_override():
        yield db

    async def _get_current_user_override():
        from app.models.user import User
        result = await db.execute(_sql("SELECT id, username, password_hash, role FROM users WHERE username = 'admin'"))
        row = result.fetchone()
        return User(id=row[0], username=row[1], password_hash=row[2], role=row[3])

    app.dependency_overrides[get_db] = _get_db_override
    app.dependency_overrides[get_current_user] = _get_current_user_override

    transport = ASGITransport(app=app)
    async with AsyncClient(transport=transport, base_url="http://testserver", headers=auth_headers) as client:
        yield client

    app.dependency_overrides.clear()


